INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5a8a814-e83b-431d-9e62-64c4cda54e13', 'd6ca7678-e7ea-4b2d-ab19-cb1ead0d658a', 0, 'IAM Identity Center (formerly AWS SSO), which provides centralized, single sign-on access across all accounts in an Organization, integrating with an external identity provider or its own built-in identity store, and mapping users/groups to specific permission sets per account.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e43b1fdd-5197-4ef0-a0f3-5c8634cca6d3', 'd6ca7678-e7ea-4b2d-ab19-cb1ead0d658a', 1, 'Creating an identical IAM user manually in each of the 20 accounts, since this is the only supported way to grant multi-account access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1cd9e89-425b-48f8-85ce-f09d31df7383', 'd6ca7678-e7ea-4b2d-ab19-cb1ead0d658a', 2, 'Amazon Cognito, since Cognito is designed specifically for centralized employee access across AWS accounts within an Organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db5ac447-b8c0-4a52-a828-9a0c99c9a315', 'd6ca7678-e7ea-4b2d-ab19-cb1ead0d658a', 3, 'AWS Organizations has no mechanism to support centralized human user access across multiple accounts.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('281e33aa-859a-427b-b821-ab53698e8ccb', 'ba68fdfb-0a03-4450-b19e-5bd652832706', 0, 'Amazon GuardDuty, a managed threat detection service that continuously analyzes VPC Flow Logs, DNS logs, and CloudTrail events using threat intelligence feeds and machine learning to identify malicious or anomalous activity, with no agents to deploy or manage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2403fcff-aea2-41d0-97e0-065f214f0b30', 'ba68fdfb-0a03-4450-b19e-5bd652832706', 1, 'AWS Config, since Config''s core function is identifying malicious API calls and cryptocurrency-mining activity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fb496e0-d7ba-43e9-a0f0-7b2629f076a3', 'ba68fdfb-0a03-4450-b19e-5bd652832706', 2, 'Amazon Inspector, since Inspector continuously monitors live network traffic for malicious behavior in real time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67602f99-1f0d-430b-b639-c4d17d1cfc29', 'ba68fdfb-0a03-4450-b19e-5bd652832706', 3, 'This type of detection requires deploying a third-party agent on every single EC2 instance; no native AWS service provides it.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('387353be-36a8-4160-b4f1-d66fd86e3613', '3b9c9196-9957-4cd0-9e46-33fb78705098', 0, 'AWS Security Hub, which aggregates and normalizes findings from GuardDuty, Inspector, Config, IAM Access Analyzer, and other security services into one central dashboard, and can also run automated compliance checks against standards like CIS AWS Foundations.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81ca3125-4d7d-4a0b-98d0-67ba7191196c', '3b9c9196-9957-4cd0-9e46-33fb78705098', 1, 'AWS CloudTrail, since CloudTrail''s primary function is aggregating findings from GuardDuty, Inspector, and Config into one dashboard.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b22a3e47-0a89-43bc-9b76-7fa94aeb2f71', '3b9c9196-9957-4cd0-9e46-33fb78705098', 2, 'Amazon Macie, since Macie aggregates findings from every other AWS security service by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e16b8dc4-515a-4edf-a5c4-795d8890c933', '3b9c9196-9957-4cd0-9e46-33fb78705098', 3, 'No AWS service provides aggregated, cross-service security findings; each service must always be checked independently.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c545ebac-dbfc-4cdd-ac81-81f2c37f0495', '0f080658-1496-4715-bf70-e72567c796f8', 0, 'Systems Manager Session Manager, which establishes a secure shell session to an instance through the SSM Agent (already required for other Systems Manager features) over an outbound-only connection — no inbound port 22 needs to be open, no SSH key pairs are needed, and no bastion host is required, with all session activity optionally logged for auditing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67cdd529-d494-4736-b2e3-cd2aac97a6f1', '0f080658-1496-4715-bf70-e72567c796f8', 1, 'This requirement cannot be met without opening inbound port 22 on the instance''s Security Group.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55e0867b-f754-449e-9843-730f1e4e6b8d', '0f080658-1496-4715-bf70-e72567c796f8', 2, 'AWS Config, since Config provides interactive shell access to EC2 instances.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fccf43d-a06e-4b6d-9b54-b1628aa39e92', '0f080658-1496-4715-bf70-e72567c796f8', 3, 'Amazon Macie, since Macie''s primary function is providing SSH-less shell access to EC2 instances.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('477bb206-441e-4a63-b8f8-0d5185634bda', '7c255fae-e1dd-4363-a9bf-f8fae584dd75', 0, 'AWS Certificate Manager (ACM), which can provision a public TLS certificate for the domain and, when associated with supported services like an ALB or CloudFront, automatically renews the certificate before it expires with no manual action required.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bfea81f-f33c-419c-b6ec-4280b03c4533', '7c255fae-e1dd-4363-a9bf-f8fae584dd75', 1, 'Manually purchase a certificate from a third-party certificate authority every year and upload it to the ALB by hand each time, since ACM cannot issue or manage public TLS certificates.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9adee08-b685-4bcf-905e-a738d7cdcedd', '7c255fae-e1dd-4363-a9bf-f8fae584dd75', 2, 'AWS KMS, since KMS is the service responsible for issuing and auto-renewing public TLS certificates for ALBs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6102739d-e634-42c9-8596-66d5ce9434dd', '7c255fae-e1dd-4363-a9bf-f8fae584dd75', 3, 'TLS certificates never expire once issued, so automatic renewal is not a real consideration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2054207e-0c14-4187-b1b7-0219c395d2ae', '30b49ff4-fd67-4d06-912c-31457a962a57', 0, 'S3 bucket policies never actually take effect regardless of configuration, so this is expected and unrelated to any specific setting.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ac8b744-dd06-4717-9f39-5676c43cdb47', '30b49ff4-fd67-4d06-912c-31457a962a57', 1, 'For cross-account S3 access to actually work, BOTH the bucket owner''s bucket policy (or ACL) AND the requesting user''s own account''s IAM policy must grant the permission — access is denied if either side is missing the grant, which is a very common real-world misconfiguration when only one side has been updated.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22b3dc30-b518-4b13-bd15-8aae9531910c', '30b49ff4-fd67-4d06-912c-31457a962a57', 2, 'The object must be re-uploaded before any bucket policy change can take effect.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0add4f9-a024-49f9-b7ee-98f01a93461e', '30b49ff4-fd67-4d06-912c-31457a962a57', 3, 'IAM policies within Account B are always ignored for any resource owned by a different account.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c3cd53e-14d9-40fa-9ef9-31a2e76d7d2a', '9d15d8e9-ec44-4dd6-b7c2-28030574639a', 0, 'Latency-based routing, which routes each user''s DNS query to the Region that provides the lowest measured latency for them specifically, supporting a true multi-Region active-active architecture where both Regions serve live traffic simultaneously.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a690a815-a3f7-4d40-b49a-a2eb414e9f60', '9d15d8e9-ec44-4dd6-b7c2-28030574639a', 1, 'Failover routing, since failover routing is designed for two Regions actively serving traffic at the same time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b94b562f-984a-4bd0-98b6-3b675ea44e7f', '9d15d8e9-ec44-4dd6-b7c2-28030574639a', 2, 'Simple routing, since Simple routing automatically measures and compares latency between multiple Regions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e29d5c23-7723-4a48-be40-ca79d2e0eab8', '9d15d8e9-ec44-4dd6-b7c2-28030574639a', 3, 'Route 53 cannot route based on measured latency between Regions under any configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2717762-f07d-4f21-ab05-1fe26b42decc', '86661f9c-e5da-49c9-903b-45a4664a2a00', 0, 'Without cross-zone load balancing, the ALB distributes traffic evenly ACROSS AZs (not across individual instances) — meaning an AZ with fewer instances gives each of its instances a disproportionately larger share of that AZ''s traffic; enabling cross-zone load balancing distributes traffic evenly across ALL registered instances regardless of which AZ they''re in, correcting the imbalance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca2398bf-45bd-472c-9dd9-e91bab2270b2', '86661f9c-e5da-49c9-903b-45a4664a2a00', 1, 'Cross-zone load balancing has no effect on traffic distribution and exists purely for billing purposes.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec045e67-1ed2-4cd4-8b7e-a53f52093293', '86661f9c-e5da-49c9-903b-45a4664a2a00', 2, 'Without cross-zone load balancing, all traffic is sent exclusively to a single Availability Zone at all times.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2628ca7-4507-41f9-b56d-0b1491896950', '86661f9c-e5da-49c9-903b-45a4664a2a00', 3, 'ALBs are physically incapable of distributing traffic across more than one Availability Zone under any configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d011db7d-03b5-47b6-8ef2-ff68bcab8ef6', '94874a74-a57d-4152-9867-b92859cf7fa5', 0, 'The SNS fan-out pattern — publish the event once to an SNS topic, with multiple SQS queues (one per downstream consumer) subscribed to that same topic; SNS delivers a copy of each message to every subscribed queue independently, so each consumer gets and processes its own copy without competing with the others.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9eab185-f668-475e-8f8b-d0bb85720bfe', '94874a74-a57d-4152-9867-b92859cf7fa5', 1, 'A single SQS queue with three consumers reading from it is the correct pattern, since SQS delivers every message to every consumer simultaneously by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8017241a-afd3-4821-98e3-b92c67104f04', '94874a74-a57d-4152-9867-b92859cf7fa5', 2, 'AWS Direct Connect, since Direct Connect is designed to fan a single event out to multiple independent downstream consumers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('427b00c3-ab79-4350-93ec-83d4feb94a4d', '94874a74-a57d-4152-9867-b92859cf7fa5', 3, 'This requirement cannot be achieved using any combination of AWS messaging services.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f83b6215-7fa0-4af8-9637-0cf9c855bc6e', '6d9549cb-dc3d-4a8b-b10c-9e6031005f47', 0, 'RDS Blue/Green Deployments, which create a fully separate, synchronized "green" environment running the new engine version alongside the existing "blue" (production) environment, allowing thorough testing against the green environment before a fast, low-downtime switchover — with the original blue environment still available as a fallback immediately after switchover.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('542d8545-b4af-4a5c-aab6-1f83fd784c97', '6d9549cb-dc3d-4a8b-b10c-9e6031005f47', 1, 'A direct, immediate in-place upgrade of the production database with no parallel testing environment, since this is the only RDS upgrade mechanism available.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b698a28-ed71-4155-bf51-259b0a714bf2', '6d9549cb-dc3d-4a8b-b10c-9e6031005f47', 2, 'RDS Multi-AZ, since Multi-AZ is specifically designed for testing engine version upgrades before committing to them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f50d3222-19e2-4b69-8cef-7d04aef11cc0', '6d9549cb-dc3d-4a8b-b10c-9e6031005f47', 3, 'RDS provides no mechanism to test a database engine upgrade before it is applied to production.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08f31a26-99c1-4a24-a523-68c1a389499c', '75b6bcaa-d356-4b8b-9667-5efe698cc88c', 0, 'EBS snapshots are incremental — after the first full snapshot, each subsequent snapshot only stores the blocks that have CHANGED since the previous snapshot, not the entire volume again, which is why later snapshots are faster and consume proportionally less additional storage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8324164f-a3dc-402d-9164-d7a865ac7c1b', '75b6bcaa-d356-4b8b-9667-5efe698cc88c', 1, 'EBS automatically deletes 90% of the volume''s data before each snapshot to save space, then restores it afterward.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c051f000-e6e1-463e-a990-676702971d8e', '75b6bcaa-d356-4b8b-9667-5efe698cc88c', 2, 'Every EBS snapshot after the first is actually empty and contains no real data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bedb47e4-ba6f-44bc-a103-29c29bca8a34', '75b6bcaa-d356-4b8b-9667-5efe698cc88c', 3, 'Snapshot speed and size are unrelated to how much of the volume''s data has actually changed since the last snapshot.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2448e90e-b695-4fb8-96b2-16704c27648c', '8f362693-23ed-4ca8-8e58-992b50c0163c', 0, 'AWS Step Functions, which lets you define a workflow as a state machine of discrete steps (including Lambda invocations, waits, parallel branches, and human-approval-style pauses), providing built-in visual execution tracking, per-step retry/error-handling configuration, and support for long-running workflows spanning far longer than a single Lambda function''s maximum execution time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ee904ca-4e1f-438b-97e0-8169f29e3bcb', '8f362693-23ed-4ca8-8e58-992b50c0163c', 1, 'Amazon SQS, since SQS is specifically designed to orchestrate multi-step, stateful business workflows with visual tracking.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b684dcc6-c7aa-44b5-99ab-217e3726356a', '8f362693-23ed-4ca8-8e58-992b50c0163c', 2, 'AWS CloudFormation, since CloudFormation''s primary function is orchestrating runtime application business logic.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca629d05-e314-491c-9e4f-0ea1e05a73b2', '8f362693-23ed-4ca8-8e58-992b50c0163c', 3, 'A single large Lambda function is always the correct and only way to implement any multi-step business process.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0601f2e6-d029-4514-adf7-e30bd4c9345d', '88f57a79-be12-4503-aed6-b24d10b8186f', 0, 'API Gateway caching, which can cache responses for a configurable TTL, serving repeated identical requests directly from the cache without invoking the backend Lambda function or database at all until the cache expires.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a78e5a25-d26c-4974-ab7d-816fd8dad8fc', '88f57a79-be12-4503-aed6-b24d10b8186f', 1, 'API Gateway has no caching capability of any kind; every request always invokes the backend.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3e0123d-bd50-4fd2-9c6f-3d12f83e02e0', '88f57a79-be12-4503-aed6-b24d10b8186f', 2, 'AWS X-Ray, since X-Ray''s core function is caching API responses to reduce backend load.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('541c3965-4646-4971-b580-7725f59cf2b0', '88f57a79-be12-4503-aed6-b24d10b8186f', 3, 'AWS WAF, since WAF is responsible for caching API Gateway responses.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a7d7648-9a0d-49bc-a28a-f3f6950b69e1', '93de47d5-90e6-4a37-ad12-ef3d25c7f5f8', 0, 'Amazon Kinesis Data Streams, designed for real-time ingestion of continuous, high-volume data streams, retaining data for a configurable window during which multiple independent consumer applications can each read the same stream data at their own pace.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec2b30fd-7963-429d-9db3-e732257fb2dc', '93de47d5-90e6-4a37-ad12-ef3d25c7f5f8', 1, 'Amazon S3 Glacier, since Glacier is designed for real-time, sub-second ingestion of continuous streaming data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78399577-a143-4887-bcd8-029bc560e20e', '93de47d5-90e6-4a37-ad12-ef3d25c7f5f8', 2, 'AWS Snowball, since Snowball is designed for continuous, real-time data stream ingestion from thousands of live IoT devices.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b20432d9-65c0-45c7-80f2-7eb1ff13ff30', '93de47d5-90e6-4a37-ad12-ef3d25c7f5f8', 3, 'This kind of real-time, high-volume, multi-consumer stream ingestion is not achievable on AWS.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a312be91-ca71-4415-88c7-22196ac2e9a4', '941b1713-f08a-4db1-aaf6-9c6063001a64', 0, 'AWS Graviton (ARM-based) processor instance types, which AWS states can offer significantly better price-performance than comparable x86-based instances for many workloads — compatible workloads (using software already available for or compiled for ARM) can often switch instance types with no code changes, though workloads with x86-specific dependencies may need rebuilding/testing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b5be656-6599-47e2-b078-f34cc23ee428', '941b1713-f08a-4db1-aaf6-9c6063001a64', 1, 'T-family burstable instances, since T-family is specifically optimized for sustained, compute-intensive workloads at the lowest cost.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a4b0528-ddd9-4f14-87d5-a018a73c0b77', '941b1713-f08a-4db1-aaf6-9c6063001a64', 2, 'All EC2 processor architectures offer identical price-performance with no meaningful difference between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('726d9889-5af7-462b-8870-4c498d229744', '941b1713-f08a-4db1-aaf6-9c6063001a64', 3, 'D-family dense-storage instances, since D-family is the processor family specifically designed for better general compute price-performance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94a2a5cf-3c53-4183-87ab-2a2861f9dd90', 'a26fdde0-63f3-477c-83e0-f78b9904b868', 0, 'Yes — RDS Read Replicas use asynchronous replication from the primary, meaning there is normally a small replication lag; a replica is not guaranteed to reflect the absolute latest write at every instant, which is an expected, inherent trade-off of asynchronous replication (distinct from Multi-AZ''s synchronous standby, covered in Paper 1) in exchange for not slowing down writes on the primary.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d23ce92-9d18-48e2-a666-690e39df1aed', 'a26fdde0-63f3-477c-83e0-f78b9904b868', 1, 'No — this indicates a critical failure, since Read Replicas are always perfectly synchronous and can never lag behind the primary by even a millisecond.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00a6d7e6-cba0-4bf2-a691-c59070297a54', 'a26fdde0-63f3-477c-83e0-f78b9904b868', 2, 'No — Read Replicas do not use replication of any kind; they independently generate their own data unrelated to the primary.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e4368ae-36c9-426a-b7b2-7452c60d7e94', 'a26fdde0-63f3-477c-83e0-f78b9904b868', 3, 'This only happens if Multi-AZ is also enabled, and never occurs otherwise.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5ee68fd-ebe4-429a-bee9-3c30d37246fa', '14664ffa-b4b3-4242-8ed6-da8b2bd9f273', 0, 'A Standard Reserved Instance with a 3-year term and full upfront payment — trading maximum commitment specificity (tied to instance family/Region, less flexible than a Savings Plan) for typically the deepest available discount, appropriate specifically because this workload''s steady-state, unchanging nature means that reduced flexibility costs nothing in practice.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af74f2f1-aaae-4120-8e57-ae17f21dbc30', '14664ffa-b4b3-4242-8ed6-da8b2bd9f273', 1, 'On-Demand pricing, since On-Demand always provides a deeper discount than any 3-year commitment option for steady-state workloads.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('418b4443-385c-4e47-893c-89ed3f5bf48b', '14664ffa-b4b3-4242-8ed6-da8b2bd9f273', 2, 'Spot Instances, since Spot is the correct choice for a genuinely steady-state, always-needed production workload.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07ae5998-2233-47b0-906a-c59daa99727f', '14664ffa-b4b3-4242-8ed6-da8b2bd9f273', 3, 'There is never any pricing difference between Reserved Instances and Savings Plans under any configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('727693e0-c8e5-4d6f-a5ae-989d7b4b66d4', '3336e180-e30c-4784-b484-02fe611778a1', 0, 'S3 Storage Lens, which provides organization-wide visibility into S3 storage usage and activity metrics across all accounts/buckets in an Organization, including actionable recommendations for cost optimization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3f436d8-e906-43bd-9795-a050635c6449', '3336e180-e30c-4784-b484-02fe611778a1', 1, 'Amazon Macie, since Macie''s core function is organization-wide storage cost visibility and optimization recommendations.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb70ce7a-3b2c-4a51-a529-f4f855ff61c9', '3336e180-e30c-4784-b484-02fe611778a1', 2, 'AWS Config, since Config is specifically designed for aggregating S3 storage cost trends across an Organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f44707d9-6c0d-4f27-b074-27fcb3124913', '3336e180-e30c-4784-b484-02fe611778a1', 3, 'No AWS service provides organization-wide S3 storage visibility; each bucket must be checked individually.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e96a5b97-fe32-41da-9d8d-2552e685471b', 'd4489f60-1f93-46ed-9cd5-da090ff96bd3', 0, 'EBS volumes are billed for their provisioned storage regardless of whether they are currently attached to a running instance; an unattached ("orphaned") volume continues to incur storage charges until it is either reattached and used, or deleted if no longer needed — this is a common, real cost leak from instance termination without cleaning up its associated storage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c58032a1-b858-41f7-acc6-49b48ad3237a', 'd4489f60-1f93-46ed-9cd5-da090ff96bd3', 1, 'EBS volumes are always free once their originally attached instance is terminated, so this billing must be an error unrelated to the volumes themselves.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90ae4bd9-009c-4c82-8b74-d5ee133878d6', 'd4489f60-1f93-46ed-9cd5-da090ff96bd3', 2, 'EBS volumes automatically delete themselves within 24 hours of their instance terminating, with no possible exception.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d96075b8-4c9f-4145-a372-8c3ae53402e5', 'd4489f60-1f93-46ed-9cd5-da090ff96bd3', 3, 'Unattached EBS volumes can only be billed if they are explicitly re-attached to a new instance first.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1610ca7f-53e0-4b73-bc5f-86afd15dc368', '8b782934-3b55-4d80-839d-175ecf0e02f0', 0, 'AWS Trusted Advisor, which checks an account against best practices across multiple categories — including a Cost Optimization category that flags idle/underutilized resources like low-utilization EC2 instances, unattached EBS volumes, and idle RDS instances — alongside separate Security, Performance, Fault Tolerance, and Service Limits categories, all in one consolidated tool.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('afdc533b-7b71-45d3-9173-0c909c7898fd', '8b782934-3b55-4d80-839d-175ecf0e02f0', 1, 'AWS Direct Connect, since Direct Connect''s core function is identifying idle and underutilized compute/storage resources.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20f3b1b5-1a14-44e9-90c9-085e626fafd6', '8b782934-3b55-4d80-839d-175ecf0e02f0', 2, 'Amazon Route 53, since Route 53 is responsible for surfacing cost-optimization findings across EC2, EBS, and RDS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca3ec3a1-07db-4a1d-9c87-1055c61ab5e2', '8b782934-3b55-4d80-839d-175ecf0e02f0', 3, 'No AWS service besides manually written custom scripts can identify underutilized resources across an account.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
